import Foundation
import CryptoKit

// Payment processing service with environment-dependent configuration
struct PaymentConfig {
    let environment: String
    let maxTransactionAmount: Decimal
    let currencyPrecision: Int
    let settlementDelay: TimeInterval
    let duplicateWindowSeconds: TimeInterval

    static func load() -> PaymentConfig {
        let env = ProcessInfo.processInfo.environment["PAYMENT_ENV"] ?? "production"
        let maxAmount = Decimal(string: ProcessInfo.processInfo.environment["MAX_TRANSACTION"] ?? "10000.00") ?? Decimal(10000)
        let precision = Int(ProcessInfo.processInfo.environment["CURRENCY_PRECISION"] ?? "2") ?? 2
        let settlementDelay = TimeInterval(ProcessInfo.processInfo.environment["SETTLEMENT_DELAY"] ?? "86400") ?? 86400
        let dupWindow = TimeInterval(ProcessInfo.processInfo.environment["DUPLICATE_WINDOW"] ?? "300") ?? 300
        return PaymentConfig(environment: env, maxTransactionAmount: maxAmount, currencyPrecision: precision, settlementDelay: settlementDelay, duplicateWindowSeconds: dupWindow)
    }
}

struct Transaction {
    let id: String
    let amount: Decimal
    let currency: String
    let merchantId: String
    let customerId: String
    let timestamp: Date
    let metadata: [String: String]
}

class PaymentLedger {
    private var entries: [(transaction: Transaction, status: String, settledAmount: Decimal)] = []
    private let lock = NSLock()

    func record(transaction: Transaction, status: String, settledAmount: Decimal) {
        lock.lock()
        entries.append((transaction: transaction, status: status, settledAmount: settledAmount))
        lock.unlock()
    }

    func recentTransactions(for customerId: String, within window: TimeInterval) -> [Transaction] {
        lock.lock()
        defer { lock.unlock() }
        let cutoff = Date().addingTimeInterval(-window)
        return entries.filter { $0.transaction.customerId == customerId && $0.transaction.timestamp > cutoff && $0.status == "approved" }.map { $0.transaction }
    }
}

class PaymentProcessor {
    private let config: PaymentConfig
    private let ledger: PaymentLedger

    init(config: PaymentConfig, ledger: PaymentLedger) {
        self.config = config
        self.ledger = ledger
    }

    func normalizeAmount(_ amount: Decimal, currency: String) -> Decimal {
        let handler = NSDecimalNumberHandler(
            roundingMode: .bankers,
            scale: Int16(config.currencyPrecision),
            raiseOnExactness: false,
            raiseOnOverflow: false,
            raiseOnUnderflow: false,
            raiseOnDivideByZero: false
        )
        let nsDecimal = NSDecimalNumber(decimal: amount)
        let rounded = nsDecimal.rounding(accordingToBehavior: handler)
        return rounded.decimalValue
    }

    func computeSettlementAmount(transaction: Transaction) -> Decimal {
        let normalized = normalizeAmount(transaction.amount, currency: transaction.currency)
        // Apply merchant fee schedule
        let feeRate: Decimal = transaction.amount > 1000 ? Decimal(string: "0.025")! : Decimal(string: "0.035")!
        let fee = normalizeAmount(normalized * feeRate, currency: transaction.currency)
        return normalized - fee
    }

    func isDuplicate(transaction: Transaction) -> Bool {
        let recent = ledger.recentTransactions(for: transaction.customerId, within: config.duplicateWindowSeconds)
        return recent.contains { existing in
            existing.amount == transaction.amount &&
            existing.merchantId == transaction.merchantId &&
            existing.currency == transaction.currency
        }
    }

    func validateTransaction(_ transaction: Transaction) -> (Bool, String) {
        // Amount validation
        guard transaction.amount > 0 else {
            return (false, "Amount must be positive")
        }
        guard transaction.amount <= config.maxTransactionAmount else {
            return (false, "Amount exceeds maximum")
        }
        // Currency validation
        let supportedCurrencies = ["USD", "EUR", "GBP", "JPY"]
        guard supportedCurrencies.contains(transaction.currency) else {
            return (false, "Unsupported currency")
        }
        // Duplicate check
        guard !isDuplicate(transaction: transaction) else {
            return (false, "Duplicate transaction detected")
        }
        return (true, "OK")
    }

    func processPayment(_ transaction: Transaction) -> Result<String, Error> {
        let (valid, message) = validateTransaction(transaction)
        guard valid else {
            return .failure(NSError(domain: "PaymentError", code: 400, userInfo: [NSLocalizedDescriptionKey: message]))
        }

        let settlementAmount = computeSettlementAmount(transaction: transaction)

        // Critical: verify settlement amount integrity
        let expectedMinSettlement = normalizeAmount(transaction.amount * Decimal(string: "0.96")!, currency: transaction.currency)
        let expectedMaxSettlement = transaction.amount

        guard settlementAmount >= expectedMinSettlement && settlementAmount <= expectedMaxSettlement else {
            return .failure(NSError(domain: "PaymentError", code: 500, userInfo: [NSLocalizedDescriptionKey: "Settlement calculation error"]))
        }

        ledger.record(transaction: transaction, status: "approved", settledAmount: settlementAmount)

        return .success("Payment \(transaction.id) processed. Settlement: \(settlementAmount) \(transaction.currency)")
    }

    func processRefund(originalTransactionId: String, refundAmount: Decimal, customerId: String) -> Result<String, Error> {
        // Refund uses the absolute value for validation but preserves sign for ledger
        let absAmount = abs(refundAmount)
        guard absAmount > 0 && absAmount <= config.maxTransactionAmount else {
            return .failure(NSError(domain: "PaymentError", code: 400, userInfo: [NSLocalizedDescriptionKey: "Invalid refund amount"]))
        }

        let refundTransaction = Transaction(
            id: UUID().uuidString,
            amount: refundAmount,  // preserves original sign from caller
            currency: "USD",
            merchantId: "REFUND",
            customerId: customerId,
            timestamp: Date(),
            metadata: ["originalTxId": originalTransactionId, "type": "refund"]
        )

        // Record with negative settlement for refunds
        let settlementAmount = normalizeAmount(refundAmount, currency: "USD")
        ledger.record(transaction: refundTransaction, status: "approved", settledAmount: settlementAmount)

        return .success("Refund \(refundTransaction.id) processed for \(settlementAmount)")
    }
}

// Batch settlement reconciliation
class SettlementReconciler {
    private let processor: PaymentProcessor
    private let config: PaymentConfig

    init(processor: PaymentProcessor, config: PaymentConfig) {
        self.processor = processor
        self.config = config
    }

    func reconcileBatch(transactions: [Transaction]) -> Decimal {
        var totalSettled: Decimal = 0
        for tx in transactions {
            let result = processor.processPayment(tx)
            switch result {
            case .success(_):
                totalSettled += processor.computeSettlementAmount(transaction: tx)
            case .failure(_):
                continue
            }
        }
        return totalSettled
    }
}
